app.get('/api/preferences/notifications',{preHandler:requireAuth},async(req:Req)=>{const row=await one(`SELECT preferences FROM user_preferences WHERE user_id=$1 AND gym_id=$2`,[req.user!.id,req.user!.gym_id]);return row?.preferences||{expiry:true,financial:true};});
