app.put('/api/security/password',{preHandler:requireAuth},async(req:Req,reply)=>{const b=body(req);if(!b.current_password||!b.new_password||String(b.new_password).length<8)return reply.code(400).send({error:'Informe a senha atual e uma nova senha com pelo menos 8 caracteres.'});const u=await one(`SELECT password_hash FROM users WHERE id=$1 AND gym_id=$2`,[req.user!.id,req.user!.gym_id]);if(!u||!(await argon2.verify(u.password_hash,b.current_password)))return reply.code(400).send({error:'Senha atual inválida.'});const hash=await argon2.hash(b.new_password);await q(`UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2 AND gym_id=$3`,[hash,req.user!.id,req.user!.gym_id]);await q(`UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND token_hash<>$2 AND revoked_at IS NULL`,[req.user!.id,hashToken((req.headers.authorization||'').slice(7))]);return {ok:true};});

app.get('/api/settings/gym',{preHandler:requireAuth},async(req:Req)=>one(`SELECT id,name,slug,logo_url,cnpj,phone,email,address,timezone FROM gyms WHERE id=$1`,[req.user!.gym_id]));
const logoValue=(value:any)=>{const v=String(value??'').trim();if(!v)return null;if(/^https?:\/\//i.test(v))return v.slice(0,2048);if(/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/i.test(v)&&v.length<=700000)return v;return undefined;};
app.put('/api/settings/gym',{preHandler:[requireAuth,requireManagement]},async(req:Req,reply)=>{const b=body(req),logo=logoValue(b.logo_url);if(logo===undefined)return reply.code(400).send({error:'Logo inválido. Use PNG, JPG ou WEBP de até 512 KB.'});return one(`UPDATE gyms SET name=$1,logo_url=$2,cnpj=$3,phone=$4,email=$5,address=$6,timezone=$7,updated_at=now() WHERE id=$8 RETURNING *`,[String(b.name||'').slice(0,160),logo,String(b.cnpj||'').slice(0,18)||null,String(b.phone||'').slice(0,30)||null,String(b.email||'').slice(0,254)||null,b.address||{},b.timezone||'America/Sao_Paulo',req.user!.gym_id]);});


// Portal do aluno
const studentAuth = async (req:any, reply:FastifyReply) => {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return reply.code(401).send({error:'Não autenticado'});
  const row = await one(`SELECT sa.student_id,sa.gym_id,s.full_name,s.email,s.phone,g.name gym_name,g.logo_url gym_logo_url FROM student_sessions ss JOIN student_accounts sa ON sa.id=ss.student_account_id JOIN students s ON s.id=sa.student_id JOIN gyms g ON g.id=sa.gym_id WHERE ss.token_hash=$1 AND ss.student_account_id=sa.id AND ss.gym_id=sa.gym_id AND sa.gym_id=s.gym_id AND s.gym_id=g.id AND ss.revoked_at IS NULL AND ss.expires_at>now() AND sa.status='active' AND s.status='active' AND g.active=true`, [hashToken(header.slice(7))]);
  if (!row) return reply.code(401).send({error:'Sessão expirada'}); req.student=row;
};
app.post('/student-auth/login',async(req,reply)=>{ const b=body(req); if(!b.gymSlug||!b.email||!b.password)return reply.code(400).send({error:'Informe academia, e-mail e senha'}); const account=await one(`SELECT sa.*,s.full_name,s.email student_email,s.phone,g.name gym_name,g.logo_url gym_logo_url FROM student_accounts sa JOIN students s ON s.id=sa.student_id JOIN gyms g ON g.id=sa.gym_id WHERE g.slug=$1 AND lower(sa.email)=lower($2) AND sa.status='active' AND s.status='active' AND g.active=true`,[b.gymSlug,b.email]); if(!account||!(await argon2.verify(account.password_hash,b.password)))return reply.code(401).send({error:'E-mail ou senha inválidos'}); const token=newToken(); await q(`INSERT INTO student_sessions(student_account_id,gym_id,token_hash,expires_at) VALUES($1,$2,$3,now()+interval '7 days')`,[account.id,account.gym_id,hashToken(token)]); await q(`UPDATE student_accounts SET last_login_at=now() WHERE id=$1`,[account.id]); return {token,student:{id:account.student_id,name:account.full_name,email:account.student_email||account.email,phone:account.phone,gymName:account.gym_name,gymLogo:account.gym_logo_url||null}}; });
