app.get('/student-api/home',{preHandler:studentAuth},async(req:any)=>{ const g=req.student.gym_id,id=req.student.student_id; await generateAssistantWorkout(g,id,0); const [enrollment,workouts,appointments,payments]=await Promise.all([one(`SELECT e.starts_on,e.ends_on,e.status,p.name plan_name,p.price FROM enrollments e JOIN plans p ON p.id=e.plan_id WHERE e.student_id=$1 AND e.gym_id=$2 ORDER BY e.ends_on DESC LIMIT 1`,[id,g]),q(`SELECT w.id,w.name,w.objective,w.review_on,w.starts_on,w.status,COALESCE(json_agg(json_build_object('id',x.id,'name',x.name,'muscle_group',x.muscle_group,'equipment',x.equipment,'instructions',x.instructions,'sets',we.sets,'reps',we.reps,'load',we.load,'rest',we.rest,'notes',we.notes) ORDER BY we.position) FILTER(WHERE x.id IS NOT NULL),'[]') exercises FROM workouts w LEFT JOIN workout_exercises we ON we.workout_id=w.id LEFT JOIN exercises x ON x.id=we.exercise_id WHERE w.student_id=$1 AND w.gym_id=$2 AND w.status='active' AND NOT EXISTS(SELECT 1 FROM workout_completions wc WHERE wc.workout_id=w.id AND wc.student_id=w.student_id) GROUP BY w.id ORDER BY (w.starts_on IS NULL OR w.starts_on<=CURRENT_DATE) DESC,w.starts_on ASC NULLS LAST,w.updated_at DESC LIMIT 1`,[id,g]),q(`SELECT id,title,type,starts_at,ends_at,notes FROM appointments WHERE student_id=$1 AND gym_id=$2 AND starts_at>=now() ORDER BY starts_at LIMIT 20`,[id,g]),q(`SELECT amount,paid_at,method,status,due_at FROM payments WHERE student_id=$1 AND gym_id=$2 ORDER BY created_at DESC LIMIT 20`,[id,g])]); return {student:{id,name:req.student.full_name,email:req.student.email,phone:req.student.phone,gymName:req.student.gym_name,gymLogo:req.student.gym_logo_url||null},enrollment:enrollment||null,workouts,appointments,payments}; });
