app.post('/student-api/face/checkin',{preHandler:studentAuth},async(req:any,reply)=>{const g=req.student.gym_id,id=req.student.student_id,b=body(req),descriptor=b.descriptor;if(!Array.isArray(descriptor)||descriptor.length<64||descriptor.some((x:any)=>!Number.isFinite(Number(x))))return reply.code(400).send({error:'Não foi possível ler o rosto. Tente novamente.'});const profile=await one(`SELECT descriptor_encrypted FROM face_profiles WHERE gym_id=$1 AND student_id=$2 AND revoked_at IS NULL`,[g,id]);if(!profile)return reply.code(409).send({error:'O reconhecimento facial ainda não está cadastrado para este aluno. Peça à academia para cadastrá-lo no perfil.'});let enrolled:any;try{enrolled=JSON.parse(decrypt(profile.descriptor_encrypted))}catch{return reply.code(500).send({error:'Não foi possível validar o cadastro facial.'});}if(!Array.isArray(enrolled)||enrolled.length!==descriptor.length)return reply.code(400).send({error:'O cadastro facial precisa ser atualizado pela academia.'});let sum=0;for(let i=0;i<enrolled.length;i++){const diff=Number(enrolled[i])-Number(descriptor[i]);sum+=diff*diff;}const distance=Math.sqrt(sum),threshold=.52;if(distance>threshold)return reply.code(401).send({error:'Rosto diferente do cadastro. Posicione-se novamente e tente outra vez.'});const existing=await one(`SELECT * FROM checkins WHERE gym_id=$1 AND student_id=$2 AND checked_at>=CURRENT_DATE`,[g,id]);if(existing)return {already:true,checkin:existing};const enrollment=await one(`SELECT ends_on FROM enrollments WHERE gym_id=$1 AND student_id=$2 AND status<>'cancelled' ORDER BY ends_on DESC LIMIT 1`,[g,id]);if(enrollment?.ends_on&&new Date(enrollment.ends_on)<new Date())return reply.code(400).send({error:'Sua matrícula está vencida.'});const checkin=await one(`INSERT INTO checkins(gym_id,student_id,method,confidence) VALUES($1,$2,'face',$3) RETURNING *`,[g,id,Math.max(0,1-distance/threshold)]);return reply.code(201).send({already:false,checkin});});
