  if(!rawContext.profile) return {text:'Complete seu perfil nutricional para receber orientações gerais. Este assistente não substitui um nutricionista.'};
  const restrictions=context.profile?.allergies||context.profile?.restrictions,latest=rawContext.meals?.[0],hint=latest?` Seu último registro foi ${latest.meal_type.toLowerCase()}.`:'';
  let ai:string|null=null;let action:any=null;const lower=message.toLowerCase().trim();
  const waterMatch=lower.match(/^(?:bebi|tomei|adicionei|registrei)\\s+(?:água\\s+)?(\\d+(?:[.,]\\d+)?)\\s*(ml|mililitros|l|litros)\\b/);
  if(!imageDataUrl&&waterMatch){let amount=Number(waterMatch[1].replace(',','.'));if(['l','litros'].includes(waterMatch[2]))amount*=1000;if(amount>=1&&amount<=10000){await q(`INSERT INTO nutrigym_hydration(gym_id,student_id,hydration_date,amount_ml,hydration_time) VALUES($1,$2,CURRENT_DATE,$3,LOCALTIME)`,[s.gym,s.student,Math.round(amount)]);action={type:'hydration',amount_ml:Math.round(amount)};await recordAssistantEvent(s.gym,s.student,'nutrigym','HYDRATION_REGISTERED',{amount_ml:Math.round(amount),source:'chat'});}}
