app.get('/student-api/nutrigym/memories',{preHandler:studentAuth},async(req:any)=>{const s=nutritionScope(req);return q(`SELECT id,memory_key,memory_value,created_at,updated_at FROM nutrigym_memories WHERE gym_id=$1 AND student_id=$2 AND active=true ORDER BY updated_at DESC`,[s.gym,s.student]);});
app.post('/student-api/nutrigym/memories',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),key=nutritionText(b.memory_key??b.key,80,true),value=nutritionText(b.memory_value??b.value,500,true);if(key===undefined||value===undefined)return reply.code(400).send({error:'Informe a memória.'});return reply.code(201).send(await one(`INSERT INTO nutrigym_memories(gym_id,student_id,memory_key,memory_value) VALUES($1,$2,$3,$4) RETURNING id,memory_key,memory_value,created_at,updated_at`,[s.gym,s.student,key,value]));});
app.put('/student-api/nutrigym/memories/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),key=nutritionText(b.memory_key??b.key,80,true),value=nutritionText(b.memory_value??b.value,500,true);if(key===undefined||value===undefined)return reply.code(400).send({error:'Informe a memória.'});const row=await one(`UPDATE nutrigym_memories SET memory_key=$1,memory_value=$2,updated_at=now() WHERE id=$3 AND gym_id=$4 AND student_id=$5 AND active=true RETURNING id,memory_key,memory_value,created_at,updated_at`,[key,value,(req.params as any).id,s.gym,s.student]);return row||reply.code(404).send({error:'Memória não encontrada'});});
app.delete('/student-api/nutrigym/memories/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),row=await one(`UPDATE nutrigym_memories SET active=false,updated_at=now() WHERE id=$1 AND gym_id=$2 AND student_id=$3 RETURNING id`,[(req.params as any).id,s.gym,s.student]);return row?{ok:true}:reply.code(404).send({error:'Memória não encontrada'});});
app.get('/student-api/nutrigym/shopping',{preHandler:studentAuth},async(req:any)=>{const s=nutritionScope(req);return q(`SELECT id,category,item,quantity,purchased,created_at,updated_at FROM nutrigym_shopping_items WHERE gym_id=$1 AND student_id=$2 ORDER BY purchased,category,item`,[s.gym,s.student]);});
app.post('/student-api/nutrigym/shopping',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),category=nutritionText(b.category,40)||'Outros',item=nutritionText(b.item,160,true),quantity=nutritionText(b.quantity,60);if(item===undefined)return reply.code(400).send({error:'Informe o item.'});return reply.code(201).send(await one(`INSERT INTO nutrigym_shopping_items(gym_id,student_id,category,item,quantity) VALUES($1,$2,$3,$4,$5) RETURNING *`,[s.gym,s.student,category,item,quantity]));});
app.put('/student-api/nutrigym/shopping/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),b=body(req),purchased=b.purchased===undefined?false:Boolean(b.purchased),item=nutritionText(b.item,160,true),quantity=nutritionText(b.quantity,60);if(item===undefined)return reply.code(400).send({error:'Informe o item.'});const row=await one(`UPDATE nutrigym_shopping_items SET item=$1,quantity=$2,purchased=$3,updated_at=now() WHERE id=$4 AND gym_id=$5 AND student_id=$6 RETURNING *`,[item,quantity,purchased,(req.params as any).id,s.gym,s.student]);return row||reply.code(404).send({error:'Item não encontrado'});});
app.delete('/student-api/nutrigym/shopping/:id',{preHandler:studentAuth},async(req:any,reply)=>{const s=nutritionScope(req),row=await one(`DELETE FROM nutrigym_shopping_items WHERE id=$1 AND gym_id=$2 AND student_id=$3 RETURNING id`,[(req.params as any).id,s.gym,s.student]);return row?{ok:true}:reply.code(404).send({error:'Item não encontrado'});});

async function init(){ const schema=await fs.readFile(path.join(process.cwd(),'schema/001_schema.sql'),'utf8'); await pool.query(schema); await pool.query(`ALTER TABLE plans ADD COLUMN IF NOT EXISTS price numeric(12,2) NOT NULL DEFAULT 0; ALTER TABLE plans ADD COLUMN IF NOT EXISTS duration_days int NOT NULL DEFAULT 30; ALTER TABLE plans ADD COLUMN IF NOT EXISTS description text; ALTER TABLE plans ADD COLUMN IF NOT EXISTS status varchar(20) NOT NULL DEFAULT 'active'; ALTER TABLE plans ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now(); CREATE TABLE IF NOT EXISTS student_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, student_id uuid NOT NULL UNIQUE REFERENCES students(id) ON DELETE CASCADE, email varchar(254) NOT NULL, password_hash text NOT NULL, status varchar(20) NOT NULL DEFAULT 'active', last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(gym_id,email)); CREATE TABLE IF NOT EXISTS student_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), student_account_id uuid NOT NULL REFERENCES student_accounts(id) ON DELETE CASCADE, gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS student_sessions_lookup_idx ON student_sessions(token_hash) WHERE revoked_at IS NULL; CREATE TABLE IF NOT EXISTS workout_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, workout_id uuid NOT NULL REFERENCES workouts(id) ON DELETE CASCADE, exercise_id uuid NOT NULL REFERENCES exercises(id), set_number int NOT NULL CHECK(set_number>0), weight numeric(10,2) NOT NULL CHECK(weight>=0), reps int NOT NULL CHECK(reps>0), completed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS workout_logs_student_idx ON workout_logs(student_id,completed_at DESC); CREATE TABLE IF NOT EXISTS workout_completions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gym_id uuid NOT NULL REFERENCES gyms(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE, workout_id uuid NOT NULL REFERENCES workouts(id), completed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS workout_completions_student_idx ON workout_completions(student_id,completed_at DESC);`); const nutrition=await fs.readFile(path.join(process.cwd(),'schema/002_nutrigym.sql'),'utf8'); await pool.query(nutrition); const nutritionPlus=await fs.readFile(path.join(process.cwd(),'schema/003_nutrigym_plus.sql'),'utf8'); await pool.query(nutritionPlus); const nutritionChat=await fs.readFile(path.join(process.cwd(),'schema/004_nutrigym_chat.sql'),'utf8'); await pool.query(nutritionChat); const nutritionOnboarding=await fs.readFile(path.join(process.cwd(),'schema/005_nutrigym_onboarding.sql'),'utf8'); await pool.query(nutritionOnboarding); const personalGym=await fs.readFile(path.join(process.cwd(),'schema/006_personalgym.sql'),'utf8'); await pool.query(personalGym); const preEnrollment=await fs.readFile(path.join(process.cwd(),'schema/007_pre_enrollment.sql'),'utf8'); await pool.query(preEnrollment); const preEnrollmentConsent=await fs.readFile(path.join(process.cwd(),'schema/008_pre_enrollment_consent.sql'),'utf8'); await pool.query(preEnrollmentConsent); const announcements=await fs.readFile(path.join(process.cwd(),'schema/009_announcements.sql'),'utf8'); await pool.query(announcements); const mealVision=await fs.readFile(path.join(process.cwd(),'schema/010_nutrigym_meal_vision.sql'),'utf8'); await pool.query(mealVision); const mealVisionDiagnostics=await fs.readFile(path.join(process.cwd(),'schema/011_meal_vision_diagnostics.sql'),'utf8'); await pool.query(mealVisionDiagnostics); const assistantV2=await fs.readFile(path.join(process.cwd(),'schema/012_assistant_v2.sql'),'utf8'); await pool.query(assistantV2); const assistantMemoryState=await fs.readFile(path.join(process.cwd(),'schema/013_assistant_memory_state.sql'),'utf8'); await pool.query(assistantMemoryState); const assistantWorkoutGeneration=await fs.readFile(path.join(process.cwd(),'schema/014_assistant_workout_generation.sql'),'utf8'); await pool.query(assistantWorkoutGeneration); const dailyWorkoutSequence=await fs.readFile(path.join(process.cwd(),'schema/015_daily_workout_sequence.sql'),'utf8'); await pool.query(dailyWorkoutSequence); const financialReceipts=await fs.readFile(path.join(process.cwd(),'schema/016_financial_receipts.sql'),'utf8'); await pool.query(financialReceipts); const cashReconciliation=await fs.readFile(path.join(process.cwd(),'schema/017_cash_reconciliation.sql'),'utf8'); await pool.query(cashReconciliation); const userPreferences=await fs.readFile(path.join(process.cwd(),'schema/018_user_preferences.sql'),'utf8'); await pool.query(userPreferences); }

app.setErrorHandler((err,req,reply)=>{app.log.error(err);reply.code(500).send({error:'Erro interno do servidor'});});
